"use strict";(function(){function p(t){let e=(n,...i)=>l(o(t,n),n,...i).join("");return e.asArray=(n,...i)=>l(o(t,n),...i),e}function s(t){let e=(...n)=>l(t,...n).join("");return e.asArray=(...n)=>l(t,...n),e}function o(t,e){return t[i18n.quantity(e)]||t.other||t.one||""}function l(t,...e){let n=t.split(/(%(?:\d\$)?s)/);if(e.length){let i=n.indexOf("%s");if(i!=-1)n[i]=e[0];else for(let r=0;r<e.length;r++){let f=n.indexOf("%"+(r+1)+"$s");f!=-1&&(n[f]=e[r])}}return n}
let i=window.i18n.puzzleTheme={};i['advancedPawn']="Pedinu avanzatu";i['advancedPawnDescription']="Unu di i vostri pedini hè avanzatu in a pusizione di l' aversariu, podassi chì a so promuzoin hè una minaccia.";i['advantage']="Vantaghju";i['advantageDescription']="Ùn perdite l' uccasione di piglià un vantaghju decisivu. (200cp ≤ eval ≤ 600cp)";i['anastasiaMate']="U mattu d' Anastasia";i['anastasiaMateDescription']="Un cavallu è una torra o una dama travaglianu inseme pè catturà u rè uppostu trà u bordu di a scacchera è una pezza di u so campu.";i['arabianMate']="Scaccumattu arabu";i['arabianMateDescription']="Un cavallu è una torra o una dama travaglianu inseme pè catturà u rè uppostu in un scornu di a scacchera.";i['attackingF2F7']="Attacchendu f2 o f7";i['attackingF2F7Description']="Un attaccu cuncentratu nantu à u pedinu f2 o f7, cum'è in l' attaccu figatellu.";i['attraction']="Attrazzione";i['attractionDescription']="Un barattu o un sacrifiziu attira una pezza nantu à una cantarella induv'ella hè a sibula d' una tattica.";i['backRankMate']="U mattu di u curridore";i['backRankMateDescription']="Scaccumattà u rè in a prima filare, quand' ellu hè bluccatu da i so pedini.";i['balestraMate']="Balestra mate";i['balestraMateDescription']="A bishop delivers the checkmate, while a queen blocks the remaining escape squares";i['bishopEndgame']="Finale d' alfieri";i['bishopEndgameDescription']="Una fine di partita cù soltantu alfieri è pedini.";i['blindSwineMate']="Blind Swine mate";i['blindSwineMateDescription']="Two rooks team up to mate the king in an area of 2 by 2 squares.";i['bodenMate']="Scaccumattu di Boden";i['bodenMateDescription']="2 alfieri chì cuntrollanu 2 i diagunalichì s' incrocianu danu un scaccumattu à un rè bluccatu da e so pezze.";i['capturingDefender']="Catturà u difendidore";i['capturingDefenderDescription']="Removing a piece that is critical to defence of another piece, allowing the now undefended piece to be captured on a following move.";i['castling']="Arruccamentu";i['castlingDescription']="Mette u rè à l' aggrottu, è sviluppa a torra pè l' attaccu.";i['clearance']="Liquidazione";i['clearanceDescription']="U move, à spessu cù un tempò, chì viota una cantarella, una culonna o una diagonale, pè lampà una incroccula tattica.";i['collinearMove']="Collinear move";i['collinearMoveDescription']="Two opposing pieces face each other, and one slides along the line of attack without capturing the enemy piece.";i['cornerMate']="Corner mate";i['cornerMateKnightDeliversDescription']="Confine the king to the corner using a rook or queen, and use a knight to deliver the checkmate.";i['crushing']="Sfracellu";i['crushingDescription']="Sfuttà u sbagliu di l' aversariu per uttene un vantaghju decisivu. (eval ≥ 600cp)";i['defensiveMove']="Colpu di difesa";i['defensiveMoveDescription']="A precise move or sequence of moves that is needed to avoid losing material or another advantage.";i['deflection']="Sviata";i['deflectionDescription']="A move that distracts an opposing piece from another duty that it performs, such as guarding a key square. Sometimes also called \"overloading\".";i['discoveredAttack']="Attaccu scappellatu";i['discoveredAttackDescription']="Moving a piece (such as a knight), that previously blocked an attack by a long range piece (such as a rook), out of the way of that piece.";i['discoveredCheck']="Discovered check";i['discoveredCheckDescription']="Move a piece to reveal a check from a hidden attacking piece, which often leads to a decisive advantage.";i['doubleBishopMate']="Scaccu mattu cù dui alfieri";i['doubleBishopMateDescription']="2 alfieri chì cuntrollanu 2 i diagunali vicine danu un scaccumattu à un rè bluccatu da e so pezze.";i['doubleCheck']="Scaccu doppiu";i['doubleCheckDescription']="Checking with two pieces at once, as a result of a discovered attack where both the moving piece and the unveiled piece attack the opponent's king.";i['dovetailMate']="Mattu di Cozio";i['dovetailMateDescription']="Una dama dà un scaccumattu à un rè accantu à ella ch' ùn pò scappà postu ch'ellu hè bluccatu da e so pezze.";i['endgame']="Finale";i['endgameDescription']="A tactic during the last phase of the game.";i['enPassantAdjacentCaptureDescription']="A tactic involving the en passant rule, where a pawn can capture an opposing pawn that has just moved next to it with its initial two-square move.";i['epauletteMate']="Epaulette mate";i['epauletteMateDescription']="Two adjacent escape squares for a checked king are occupied by other pieces.";i['equality']="Ugualità";i['equalityDescription']="Rivene da una pusizione perdente, è assicurà si a patta o una pusizione uguale. (val ≤ 200cp)";i['exposedKing']="Rè inariulatu";i['exposedKingDescription']="A tactic involving a king with few defenders around it, often leading to checkmate.";i['fork']="Furcina";i['forkOpposingPiecesDescription']="A move where a piece attacks two or more opposing pieces simultaneously.";i['hangingPiece']="Hanging piece";i['hangingPieceDescription']="A tactic involving an opponent piece being undefended or insufficiently defended and free to capture.";i['hookMate']="Hook mate";i['hookMateOpposingPawnDescription']="Checkmate using a rook, knight, and pawn, where an opposing pawn blocks the king's escape.";i['interference']="Interference";i['interferenceDescription']="Moving a piece between two opponent pieces to leave one or both opponent pieces undefended, such as a knight on a defended square between two rooks.";i['intermezzo']="Intermezzo";i['intermezzoDescription']="Instead of playing the expected move, first interpose another move posing an immediate threat that the opponent must answer. Also known as \"Zwischenzug\" or \"In between\".";i['killBoxMate']="Kill box mate";i['killBoxMateDescription']="A rook is next to the enemy king and supported by a queen that also blocks the king's escape squares. The rook and the queen catch the enemy king in a 3 by 3 \"kill box\".";i['kingsideAttack']="Attaccà l' arruccamentu uppostu";i['kingsideAttackDescription']="Attaccà u rè uppostu quand' ellu s' hè messu à l' agrottu per via di l' arruccamentu minò.";i['knightEndgame']="Knight endgame";i['knightEndgameDescription']="An endgame with only knights and pawns.";i['long']="Long puzzle";i['longDescription']="Three moves to win.";i['master']="Master games";i['masterDescription']="Puzzles from games played by titled players.";i['masterVsMaster']="Master vs Master games";i['masterVsMasterDescription']="Puzzles from games between two titled players.";i['mate']="Checkmate";i['mateDescription']="Win the game with style.";i['mateIn1']="Mate in 1";i['mateIn1Description']="Deliver checkmate in one move.";i['mateIn2']="Mate in 2";i['mateIn2Description']="Deliver checkmate in two moves.";i['mateIn3']="Mate in 3";i['mateIn3Description']="Deliver checkmate in three moves.";i['mateIn4']="Mate in 4";i['mateIn4Description']="Deliver checkmate in four moves.";i['mateIn5']="Mate in 5 or more";i['mateIn5Description']="Figure out a long mating sequence.";i['middlegame']="Middlegame";i['middlegameDescription']="A tactic during the second phase of the game.";i['mix']="Healthy mix";i['mixDescription']="A bit of everything. You don't know what to expect, so be ready for anything! Just like in real games.";i['morphyMateBishopAndRookDescription']="A bishop delivers checkmate to the king, while a rook helps confine it.";i['morphysMate']="Morphy's mate";i['oneMove']="One-move puzzle";i['oneMoveDescription']="A puzzle that is only one move long.";i['opening']="Opening";i['openingDescription']="A tactic during the first phase of the game.";i['operaMate']="Opera mate";i['operaMateDescription']="Check the king with a rook and use a bishop to defend the rook.";i['pawnEndgame']="Pawn endgame";i['pawnEndgameDescription']="An endgame with only pawns.";i['pillsburyMateRookAndBishopDescription']="A rook delivers checkmate to the king, while a bishop helps confine it.";i['pillsburysMate']="Pillsbury's mate";i['pin']="Pin";i['pinDescription']="A tactic involving pins, where a piece is unable to move without revealing an attack on a higher value piece.";i['playerGames']="Player games";i['playerGamesDescription']="View puzzles generated from your games, or from another player's games";i['promotePawnToQueenRookOrMinor']="Promote one of your pawns to a queen, rook or minor piece.";i['promotion']="Promotion";i['puzzleDownloadInformation']=s("These puzzles are in the public domain, and can be downloaded from %s.");i['queenEndgame']="Queen endgame";i['queenEndgameDescription']="An endgame with only queens and pawns.";i['queenRookEndgame']="Queen and Rook";i['queenRookEndgameDescription']="An endgame with only queens, rooks and pawns.";i['queensideAttack']="Queenside attack";i['queensideAttackDescription']="An attack of the opponent's king, after they castled on the queen side.";i['quietMove']="Quiet move";i['quietMoveDescription']="A move that does not check, capture, or create an immediate threat to capture. Instead, it prepares a hidden and unavoidable threat for a later move.";i['rookEndgame']="Rook endgame";i['rookEndgameDescription']="An endgame with only rooks and pawns.";i['sacrifice']="Sacrifice";i['sacrificeDescription']="A tactic involving giving up material in the short-term, to gain an advantage again after a forced sequence of moves.";i['short']="Short puzzle";i['shortDescription']="Two moves to win.";i['skewer']="Skewer";i['skewerDescription']="A motif involving a high value piece being attacked, moving out the way, and allowing a lower value piece behind it to be captured or attacked, the inverse of a pin.";i['smotheredMate']="Smothered mate";i['smotheredMateDescription']="A checkmate delivered by a knight in which the mated king is unable to move because it is surrounded (or smothered) by its own pieces.";i['superGM']="Super GM games";i['superGMDescription']="Puzzles from games played by the best players in the world.";i['swallowstailMate']="Swallow's tail mate";i['swallowstailMateDescription']="A checkmate pattern that visually resembles the appearance of a swallow’s tail, similar to a V shape.";i['trappedPiece']="Trapped piece";i['trappedPieceDescription']="A piece is unable to escape capture as it has limited moves.";i['triangleMate']="Triangle mate";i['triangleMateDescription']="The queen and rook, one square away from the enemy king, are on the same rank or file, separated by one square, forming a triangle.";i['underPromotion']="Underpromotion";i['underPromotionDescription']="Promotion to a knight, bishop, or rook.";i['veryLong']="Very long puzzle";i['veryLongDescription']="Four moves or more to win.";i['vukovicMate']="Vuković mate";i['vukovicMateDescription']="A rook and knight team up to mate the king. The rook delivers mate while supported by a third piece, and the knight is used to block the king's escape squares.";i['xRayAttack']="X-Ray attack";i['xRayAttackDescription']="A piece attacks or defends a square, through an enemy piece.";i['zugzwang']="Zugzwang";i['zugzwangDescription']="The opponent is limited in the moves they can make, and all moves worsen their position."})()